// ⓪ ENTRADA · LLAVE · CC#2 · J4 · 2026-10-13 · flujo `zero-risk/jefatura-turno` (UN paso de una revisión de la jefatura por ejecución). INACTIVO.
// Lo despierta la ruta de la jefatura (o el vigía, o este mismo flujo para el paso siguiente) con { revision_id, turno } y la llave de despacho. Nada de aquí paga: solo valida.
// A diferencia de la oficina, aquí NO hay portero: el portero y la llamada a GPT viven DENTRO de la ruta (diseño v4 §10); este flujo solo ejecuta pasos de AGENTE.
const w = $input.first().json || {}
const body = w.body && typeof w.body === 'object' && !Array.isArray(w.body) ? w.body : {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}

const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) throw new Error('JEFATURA_TURNO_CERRADO · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) · el flujo queda cerrado · E67.')
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) throw new Error('JEFATURA_TURNO_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · E67.')

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(body.revision_id || ''))) throw new Error('JEFATURA_TURNO_SIN_REVISION · revision_id no es un uuid · se DETIENE')
const t = body.turno && typeof body.turno === 'object' ? body.turno : null
if (!t || !Number.isInteger(t.n) || t.n < 1) throw new Error('JEFATURA_TURNO_SIN_NUMERO · falta turno.n (entero ≥ 1) · se DETIENE')
if (t.tipo !== 'agente') throw new Error('JEFATURA_TURNO_TIPO_INVALIDO · este flujo solo ejecuta pasos de agente (llegó ' + JSON.stringify(t.tipo) + ')')
if (!t.pedido || typeof t.pedido !== 'object') throw new Error('JEFATURA_TURNO_SIN_PEDIDO · falta turno.pedido · se DETIENE')
if (typeof t.pedido.agent_name !== 'string' || typeof t.pedido.task !== 'string' || !t.pedido.task) throw new Error('JEFATURA_TURNO_PEDIDO_INVALIDO · el pedido de un agente necesita agent_name y task')
if (typeof t.pedido.esquema !== 'string' || !t.pedido.esquema) throw new Error('JEFATURA_TURNO_SIN_ESQUEMA · el pedido de un agente necesita su esquema de salida (sin esquema no hay molde ni contrato)')
// dry_run OBLIGATORIO y booleano (diseño v4 §2): ausente o no booleano = se DETIENE, nunca se lee como «real»
if (typeof t.pedido.dry_run !== 'boolean') throw new Error('JEFATURA_TURNO_SIN_DRY_RUN · turno.pedido.dry_run debe ser booleano (true/false) · se DETIENE')

return [{ json: { revision_id: String(body.revision_id), turno: t, dry_run: t.pedido.dry_run === true } }]

// ② ARMAR EL PEDIDO · CC#2 · J4 · 2026-10-13 · el cuerpo que se manda a /api/agents/run-sdk (el agente solo se invoca desde un flujo con workflow_id) o, en modo seco, la respuesta SIMULADA.
// 🔴 En modo seco NO se llama a ningún proveedor ni al corredor: la respuesta sale de un molde válido por esquema (el «modelo simulado»), como en el turno de la oficina (r78).
// 🔴 Un esquema SIN molde no mata la ejecución ni la deja «corriendo»: devuelve un error VISIBLE al motor y la revisión cierra `fallida`.
// 🔴 `force_restart: true` y `dispatch_key` propios del paso: una respuesta vieja guardada no se reutiliza (lección del flujo de prueba).
// 🔴 Regla dura del editor (diseño v4 §2 y §9): `extra` lleva SOLO claves de una lista cerrada; JAMÁS `workflow_execution_id` (los ids de ejecución van arriba del cuerpo). Y el nodo «Agente» manda siempre `x-skip-editor-middleware: 1`.
// `pedido.simulacion` (solo con dry_run=true) fuerza ramas: fichas ninguna|sugerencia|bloquea · toma todo|nada · productor ok|formato_roto|formato_roto_siempre|muerto · version_nueva mejora|empeora|demasiado_corta · largo_a (largo del plan A) · donde.
const e = $input.first().json
const t = e.turno
const p = t.pedido

// ── lectura del propio pedido: las fichas («- [id] (gravedad) en …», como las arma la oficina) y los refs del kit / carrusel / imágenes
const idsDeFichas = (task) => [...String(task).matchAll(/^- \[([^\]\n]+)\] \((?:bloquea|sugerencia)\)/gm)].map((m) => m[1])
const indices = (task) => [...String(task).matchAll(/índice (\d+)/g)].map((m) => Number(m[1]))
const refsDeKit = (task) => [...String(task).matchAll(/^- (e\d+):/gm)].map((m) => m[1])
const refsDe = (task) => { const kit = refsDeKit(task); if (kit.length) return kit; const m = /Roles de lámina posibles[^:\n]*:\s*([^\n]+)/.exec(String(task)); return m ? m[1].split(',').map((x) => x.trim()).filter(Boolean) : [] }
const refsAGenerar = (task) => { const i = String(task).search(/## Imágenes que hay que GENERAR/); if (i < 0) return []; const sec = String(task).slice(i).split(/\n## /)[0]; return [...sec.matchAll(/^- ([^:\n]+):/gm)].map((m) => m[1].trim()) }
const sim = e.dry_run === true && p.simulacion && typeof p.simulacion === 'object' ? p.simulacion : {}
const toma = sim.toma === 'nada' ? 'nada' : 'todo'
const respuestasDe = (task) => idsDeFichas(task).map((id) => (toma === 'nada' ? { id, estado: 'no_tomada', razon: '(simulado) no lo tomo' } : { id, estado: 'tomada', razon: '(simulado) lo tomo' }))
const algunaTomada = (rs) => rs.some((r) => r.estado === 'tomada')
// el plan simulado: tres largos según el caso (la comparación contra A la hace el código de la planeación; aquí solo se fabrica el texto)
const textoDePlan = () => {
  const a = Number.isFinite(Number(sim.largo_a)) && Number(sim.largo_a) > 0 ? Number(sim.largo_a) : 25000
  const objetivo = sim.version_nueva === 'demasiado_corta' ? Math.floor(a * 0.3) : a
  const marca = sim.version_nueva === 'empeora' ? ' A calcular · TBD ·' : ''
  const base = '(simulado) línea del plan corregido.' + marca + '\n'
  return base.repeat(Math.ceil(objetivo / base.length)).slice(0, objetivo)
}

// ── moldes del modelo simulado: UNO por esquema que la jefatura puede pedir (los de la oficina, que la jefatura reutiliza, y los nuevos de re-entrega por tipo)
const SIMULADOS = {
  // jefe-marketing
  'fichas.v1': () => ({ fichas: sim.fichas === 'bloquea' || sim.fichas === 'sugerencia' ? [{ que: '(simulado) hallazgo de prueba', donde: String(sim.donde || 'texto'), contra_que: '(simulado) el manual', gravedad: sim.fichas, propuesta: '(simulado) propuesta de prueba' }] : [] }),
  // pieza (oficina): resoluciones por dueño
  'resolucion.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { pieza: { pie_de_foto: '(simulado) pie de foto corregido', hashtags: [] } } : {}) } },
  'resolucion_solo.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_copy_base.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_copy_kit.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_estructura.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_laminas.v1': (task) => ({ respuestas: respuestasDe(task) }),
  // estrategia (objeto completo), calendario (por fila o tanda) y plan (texto completo): la re-entrega de cada tipo
  'resolucion_objeto.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { objeto: { simulado: true } } : {}) } },
  'resolucion_parcial.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { filas: [] } : {}) } },
  // 🔴 el FORMATO real del texto largo del plan (bloque delimitado o esquema ≥ 40.000) lo decide la condición 1 de CC#3 (§13.5); este molde es lo único que cambia cuando se decida
  'resolucion_plan.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { texto_completo: textoDePlan() } : {}) } },
  // 🔴 EL PLAN REAL (condición 1 de CC#3): texto plano + bloque de resolución al final (no un JSON con 25–34 mil caracteres adentro). Si no se tomó nada, solo el bloque.
  'plan_texto_y_resolucion.v1': (task) => { const rs = respuestasDe(task); const bloque = '<<<RESOLUCION>>>' + String.fromCharCode(10) + JSON.stringify({ respuestas: rs }) + String.fromCharCode(10) + '<<<FIN_RESOLUCION>>>'; return algunaTomada(rs) ? textoDePlan() + String.fromCharCode(10) + bloque : bloque },
  // oficina: pasos de producción que la jefatura NO ejecuta pero cuyos moldes se conservan idénticos para la prueba de igualdad (§13.3)
  'visual_direction.v1': () => ({ resumen: '(simulado) dirección visual', decision: { modo: 'generada', motivo: '(simulado)' }, reglas_de_imagen: { obligatorio: [], prohibido: [] } }),
  'prompts.v1': () => ({ prompts: [{ prompt: '(simulado) un plato visto desde arriba con luz natural lateral, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) cenital' }, { prompt: '(simulado) el mismo plato a nivel de mesa con fondo desenfocado, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) nivel de mesa' }] }),
  'observacion_imagen.v1': (task) => { const ix = indices(task); return { imagenes: ix.map((indice) => ({ indice, reglas: [], texto_en_imagen: [], marcas: [], personas: 0 })), preferencia: ix } },
  'observacion_imagenes.v1': (task) => { const ix = indices(task); return { imagenes: ix.map((indice) => ({ indice, reglas: [], texto_en_imagen: [], marcas: [], personas: 0 })), preferencia: ix } },
  'pieza_post.v1': () => ({ pie_de_foto: '(simulado) pie de foto de prueba', hashtags: [] }),
  'direccion_imagenes.v1': (task) => { const refs = refsDe(task); return { resumen: '(simulado) dirección visual', estilo: '(simulado)', imagenes: refs.length ? [{ ref: refs[0], modo: 'generada', motivo: '(simulado)' }] : [], reglas_de_imagen: { obligatorio: [], prohibido: [] } } },
  'prompts_por_ref.v1': (task) => ({ imagenes: refsAGenerar(task).map((ref) => ({ ref, prompts: [{ prompt: '(simulado) un plato visto desde arriba con luz natural lateral, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) cenital' }, { prompt: '(simulado) el mismo plato a nivel de mesa con fondo desenfocado, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) nivel de mesa' }] })) }),
  'copy_base.v1': () => ({ texto_base: 'Primera línea simulada\nSegunda línea simulada\nTercera línea simulada\nCuarta línea simulada\nEscríbenos', pie_de_foto: '(simulado) pie de foto de prueba', hashtags: [] }),
  'laminas.v1': () => ({ laminas: [{ rol: 'hook', headline: 'Primera línea simulada' }, { rol: 'problem', headline: 'Segunda línea simulada' }, { rol: 'reframe', headline: 'Tercera línea simulada' }, { rol: 'benefit', headline: 'Cuarta línea simulada' }, { rol: 'cta', headline: 'Escríbenos', cta: 'Escríbenos' }] }),
  'estructura.v1': (task) => ({ elementos: refsDeKit(task).map((ref) => ({ ref, rol: '(simulado) rol', beat: '(simulado) beat', mood: '(simulado) mood' })) }),
  'copy_kit.v1': (task) => ({ elementos: refsDeKit(task).map((ref) => ({ ref, headline: '(simulado) titular' })) }),
}

const ERROR = (msg) => ({ ...e, simulado: true, resultado_body: { accion: 'resultado', revision_id: e.revision_id, n: t.n, error: msg, costo_usd: 0, workflow_execution_id: $execution.id } })

if (e.dry_run === true) {
  // FUENTE ÚNICA DE MOLDES (certificación de CC#3 · J2/J3 reparo 2): si la ruta entregó su `pedido.molde`, el seco contesta ESO (lo que la ruta sabe leer); los moldes de abajo son solo el respaldo cuando la ruta no trae molde (`molde_de: 'flujo'`)
  const deLaRuta = p.molde && typeof p.molde === 'object' && !Array.isArray(p.molde) ? p.molde : null
  if (deLaRuta) {
    if (typeof deLaRuta.texto !== 'string') {
      // el productor murió en la simulación de la ruta: no contesta (el vigía lo re-arma); cualquier otro motivo es un error visible, nunca «corriendo»
      if (sim.productor === 'muerto') return []
      return [{ json: { ...ERROR('JEFATURA_MOLDE_DE_LA_RUTA_SIN_TEXTO · ' + String(deLaRuta.error || 'la ruta no entregó texto para este paso')), molde_de: 'ruta' } }]
    }
    return [{ json: { ...e, simulado: true, molde_de: 'ruta', resultado_body: { accion: 'resultado', revision_id: e.revision_id, n: t.n, texto: deLaRuta.texto, costo_usd: 0, workflow_execution_id: $execution.id } } }]
  }
  const molde = SIMULADOS[p.esquema]
  // un esquema sin molde NO mata la ejecución (la revisión se quedaría «corriendo» en silencio): el motor recibe el error y la revisión falla visible
  if (!molde) return [{ json: ERROR('JEFATURA_SIN_MOLDE_SIMULADO · no hay respuesta simulada para el esquema ' + JSON.stringify(p.esquema)) }]
  // productor muerto: no contesta nunca (el vigía lo re-arma a los 12 min); en el seco la ejecución termina sin registrar nada, a propósito
  if (sim.productor === 'muerto') return []
  const roto = sim.productor === 'formato_roto_siempre' || (sim.productor === 'formato_roto' && p.reintento_formato !== true)
  const m = roto ? null : molde(p.task)
  const texto = roto ? '{"respuestas": [ {"id": ' : (typeof m === 'string' ? m : JSON.stringify(m)) // un molde de TEXTO (el plan) devuelve la cadena tal cual
  return [{ json: { ...e, simulado: true, molde_de: 'flujo', resultado_body: { accion: 'resultado', revision_id: e.revision_id, n: t.n, texto, costo_usd: 0, workflow_execution_id: $execution.id } } }]
}

// ── real: el pedido a run-sdk. Sin tope de gasto del paso NO se paga (el SDK acota el costo con max_budget_usd)
if (!(typeof p.max_budget_usd === 'number' && p.max_budget_usd > 0)) throw new Error('JEFATURA_SIN_TOPE_DEL_PASO · el pedido real no trae max_budget_usd (> 0) · no se paga un paso sin tope · se DETIENE')
const PERMITIDAS = ['indicacion_jefatura', 'paso_de_la_jefatura', 'revision_id', 'dispatch_key']
const extra = {}
for (const k of PERMITIDAS) if (p.extra && p.extra[k] !== undefined) extra[k] = p.extra[k]
extra.dispatch_key = t.dispatch_key
const cuerpo = {
  agent: p.agent_name,
  task: p.task,
  client_id: p.client_id,
  workflow_id: $workflow.id,
  workflow_execution_id: $execution.id,
  callback_url: $execution.resumeUrl,
  // la vuelta la entrega el corredor cuando el agente puede; si no puede, run-sdk lo ignora y la vuelta sigue por Vercel con la recuperación del resultado
  callback_mode: 'runner',
  force_restart: true,
  dry_run: false,
  max_budget_usd: p.max_budget_usd,
  thinking_mode: p.thinking_mode || 'disabled',
  extra,
  ...(Array.isArray(p.images) && p.images.length ? { images: p.images, images_mode: 'base64' } : {}),
}
return [{ json: { ...e, simulado: false, cuerpo } }]

// ② ¿ACEPTÓ EL PEDIDO? · CC#2 · 2026-10-09 · mismo criterio que la pieza: run-sdk contesta SÍNCRONO 202 `{accepted:true}` si acepta (la vuelta llega después por el callback) o un RECHAZO con `error`.
// Un rechazo síncrono significa que el agente NO arrancó: se avisa YA a la jefatura (resultado con error) en lugar de esperar la espera entera.
const c = $('② Armar el pedido').first().json
const e = $input.first().json || {}
const r = e.body && typeof e.body === 'object' ? e.body : e
// el nodo HTTP falló (red, tiempo): n8n entrega `{error:{message…}}` con `error` OBJETO · el rechazo de run-sdk trae `error` como TEXTO
if (r.error && typeof r.error === 'object') {
  return [{ json: { ...c, aceptado: false, resultado_body: { accion: 'resultado', revision_id: c.revision_id, n: c.turno.n, error: 'JEFATURA_PEDIDO_NO_LLEGO · ' + String(r.error.message || r.error.name || 'sin detalle').slice(0, 200), costo_usd: 0, workflow_execution_id: $execution.id } } }]
}
if (r.accepted === true) return [{ json: { ...c, aceptado: true } }]
const partes = [r.error, r.code, r.detail].filter((x) => x !== undefined && x !== null && x !== '')
return [{ json: { ...c, aceptado: false, resultado_body: { accion: 'resultado', revision_id: c.revision_id, n: c.turno.n, error: 'JEFATURA_PEDIDO_RECHAZADO · ' + (partes.length ? partes.map(String).join(' · ').slice(0, 240) : JSON.stringify(r).slice(0, 200)), costo_usd: 0, workflow_execution_id: $execution.id } } }]

// ② LA VUELTA DEL AGENTE (o el portero) · CC#2 · 2026-10-09 · convierte lo que volvió en el cuerpo de `POST /api/jefatura/turnos {accion:'resultado'}`.
// Un fallo declarado del agente (`success:false`: corte por tope, etc.) NO es una vuelta: su texto, si trae, es PARCIAL y no se manda como respuesta (se manda el error).
// El costo es el que reporta el corredor (el libro de la sala lo suma); sin costo reportado se manda 0 y la sala lo declara.
const c = $('② Armar el pedido').first().json
const e = $input.first().json || {}
const cuerpo = e.body ? e.body : e
const fallo = cuerpo.success === false ? String(cuerpo.error || cuerpo.error_kind || 'sin detalle') : null
const texto = fallo ? '' : String(cuerpo.response || cuerpo.result || cuerpo.output || cuerpo.text || '')
const costo = typeof cuerpo.cost_usd === 'number' ? cuerpo.cost_usd : (typeof cuerpo.costUsd === 'number' ? cuerpo.costUsd : 0)
const body = { accion: 'resultado', revision_id: c.revision_id, n: c.turno.n, costo_usd: costo, workflow_execution_id: $execution.id, workflow_id: $workflow.id }
if (fallo) body.error = 'el agente FALLÓ · ' + fallo + (cuerpo.partial === true ? ' · (había texto parcial: no se usa)' : '')
else if (texto.trim() === '') body.error = 'la vuelta del agente llegó vacía (o se agotó la espera)'
else body.texto = texto
if (typeof cuerpo.tokens_in === 'number') body.tokens_in = cuerpo.tokens_in
if (typeof cuerpo.tokens_out === 'number') body.tokens_out = cuerpo.tokens_out
return [{ json: { ...c, resultado_body: body } }]

// ③ ¿Y AHORA? · CC#2 · J4 · 2026-10-13 · decide qué sigue con la respuesta REAL de `POST /api/jefatura/turnos` (statusCode + body).
//   200 `esperar` → el SIGUIENTE paso: se vuelve a despertar este mismo flujo (una ejecución por paso: ninguna pasa de unos minutos)
//   200 `cerrado` → la revisión terminó (limpia, con desacuerdo, sin segunda mirada, incompleta por tope o fallida): se ENTREGA al llamador según `devolver_a`:
//                     · `devolver.tipo = 'webhook'` → se manda `devolver.cuerpo` a `devolver.url` (SOLO si la dirección es de nuestro n8n o de nuestro Vercel: nada sale a un tercero)
//                     · `devolver.tipo = 'sala_ref'` o ausente con `sala_ref` → el CABLE a la sala con el resultado REAL
//                     · `devolver.tipo = 'ninguno'` → nada (la ruta ya guardó todo; p. ej. las pruebas de la jefatura)
//   cualquier otra respuesta (409 turno no esperado, 5xx…) → se DETIENE con su motivo (nunca se da por bien)
const c = $('⓪ Entrada · llave').first().json
const e = $input.first().json || {}
if (e.error && typeof e.error === 'object') throw new Error('JEFATURA_RESULTADO_NO_LLEGO · POST /api/jefatura/turnos falló antes de recibir respuesta (' + String(e.error.message || e.error.name || 'sin detalle').slice(0, 160) + ')')
const status = Number(e.statusCode)
const b = e.body && typeof e.body === 'object' ? e.body : {}
// «ya hay un paso esperando respuesta» llega como `esperar` SIN pedido: aquí no se despierta nada (se DETIENE con su motivo, no se manda un turno vacío a otro flujo)
if (status === 200 && b.accion === 'esperar' && b.turno && !b.turno.pedido) throw new Error('JEFATURA_ESPERA_SIN_PEDIDO · la ruta contestó «esperar» sin el pedido del paso (' + String(b.nota || 'sin nota').slice(0, 120) + ') · se DETIENE')
if (status === 200 && b.accion === 'esperar' && b.turno) return [{ json: { ruta: 'esperar', turno_body: { revision_id: c.revision_id, turno: b.turno } } }]
if (status === 200 && b.accion === 'cerrado') {
  const dev = b.devolver && typeof b.devolver === 'object' ? b.devolver : null
  const ref = b.sala_ref && typeof b.sala_ref === 'object' ? b.sala_ref : {}
  const tipo = dev && typeof dev.tipo === 'string' ? dev.tipo : (b.sala_ref ? 'sala_ref' : 'ninguno')
  if (tipo === 'webhook') {
    // solo destinos REALES de un llamador (certificación de CC#3 · J4 reparo 4): los webhooks de nuestro n8n (la base ya es `…/webhook`) y SOLO las rutas `/api/jefatura/` de nuestro Vercel (no cualquier ruta suya); la llave de despacho viaja en esta entrega
    const permitidas = [String($env.N8N_WEBHOOK_BASE || 'https://n8n-production-72be.up.railway.app/webhook').replace(/\/+$/, '') + '/', 'https://zero-risk-platform.vercel.app/api/jefatura/']
    const url = String(dev.url || '')
    if (!permitidas.some((p) => url.startsWith(p))) throw new Error('JEFATURA_DESTINO_NO_PERMITIDO · devolver.url no es de nuestro n8n ni de nuestro Vercel · no se entrega a un tercero · se DETIENE (' + url.slice(0, 80) + ')')
    return [{ json: { ruta: 'webhook', entrega_url: url, entrega_cuerpo: { revision_id: c.revision_id, resultado: String(b.resultado || 'fallida'), ...(dev.cuerpo && typeof dev.cuerpo === 'object' ? dev.cuerpo : {}) } } }]
  }
  if (tipo === 'sala_ref') {
    return [{ json: { ruta: 'cable', payload_cable: {
      event_type: 'run_completed', worker_id: $workflow.id, worker_name: 'jefatura',
      resultado: String(b.resultado_para_la_sala || b.resultado || 'fallido'), revision_id: c.revision_id, con_desacuerdo: b.marcas && b.marcas.con_desacuerdo === true, sin_segunda_mirada: b.marcas && b.marcas.sin_segunda_mirada === true, simulado: b.simulado === true,
      _sala_correlation_id: ref._sala_correlation_id || null, _journey_id: ref._journey_id || null, ts: new Date().toISOString(),
    } } }]
  }
  return [{ json: { ruta: 'nada' } }]
}
throw new Error('JEFATURA_TURNO_RECHAZADO · /api/jefatura/turnos contestó ' + status + ' · ' + String(b.error || b.detalle || JSON.stringify(b)).slice(0, 240) + ' · se DETIENE')

// ② VUELTA · COMPLETAR · si la vuelta por cable no llegó, la respuesta del agente puede estar en el punto de control (workflow_checkpoints) de ESTA ejecución. Si no, todo igual que hoy.
const orig = $('② Esperar al agente').last().json || {}
const cuerpoO = orig.body ? orig.body : orig
const textoO = String(cuerpoO.response || cuerpoO.result || cuerpoO.output || cuerpoO.text || '')
if (textoO.trim().length > 0 || cuerpoO.success === false) return [{ json: orig }]
const r = $input.first().json || {}
const filas = Array.isArray(r.body) ? r.body : []
const f = Number(r.statusCode) === 200 && filas.length && filas[0] && typeof filas[0] === 'object' ? filas[0] : null
if (!f || f.step_status !== 'completed' || String(f.truncado) === 'true' || !String(f.texto || '').trim()) return [{ json: orig }]
let ack = null
try { const a = $('② Agente (run-sdk)').last().json; ack = (a.body && a.body.ack_timestamp) || a.ack_timestamp || null } catch (e) { ack = null }
const desde = ack ? new Date(ack).getTime() : NaN
// 06-nov · el punto de control se reescribe por upsert y conserva la creación de la primera vez: lo que dice si es de ESTE pedido es la actualización
const creado = new Date(f.updated_at || f.created_at).getTime()
if (!(desde > 0) || !(creado >= desde - 10000)) return [{ json: orig }]
return [{ json: { body: { response: String(f.texto), recuperada_del_punto_de_control: true } } }]

// ⓪ ENTRADA · LLAVE · CC#2 · J4 · 2026-10-13 · flujo `zero-risk/jefatura-turno` (UN paso de una revisión de la jefatura por ejecución). INACTIVO.
// Lo despierta la ruta de la jefatura (o el vigía, o este mismo flujo para el paso siguiente) con { revision_id, turno } y la llave de despacho. Nada de aquí paga: solo valida.
// A diferencia de la oficina, aquí NO hay portero: el portero y la llamada a GPT viven DENTRO de la ruta (diseño v4 §10); este flujo solo ejecuta pasos de AGENTE.
const w = $input.first().json || {}
const body = w.body && typeof w.body === 'object' && !Array.isArray(w.body) ? w.body : {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}

const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) throw new Error('JEFATURA_TURNO_CERRADO · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) · el flujo queda cerrado · E67.')
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) throw new Error('JEFATURA_TURNO_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · E67.')

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(body.revision_id || ''))) throw new Error('JEFATURA_TURNO_SIN_REVISION · revision_id no es un uuid · se DETIENE')
const t = body.turno && typeof body.turno === 'object' ? body.turno : null
if (!t || !Number.isInteger(t.n) || t.n < 1) throw new Error('JEFATURA_TURNO_SIN_NUMERO · falta turno.n (entero ≥ 1) · se DETIENE')
if (t.tipo !== 'agente') throw new Error('JEFATURA_TURNO_TIPO_INVALIDO · este flujo solo ejecuta pasos de agente (llegó ' + JSON.stringify(t.tipo) + ')')
if (!t.pedido || typeof t.pedido !== 'object') throw new Error('JEFATURA_TURNO_SIN_PEDIDO · falta turno.pedido · se DETIENE')
if (typeof t.pedido.agent_name !== 'string' || typeof t.pedido.task !== 'string' || !t.pedido.task) throw new Error('JEFATURA_TURNO_PEDIDO_INVALIDO · el pedido de un agente necesita agent_name y task')
if (typeof t.pedido.esquema !== 'string' || !t.pedido.esquema) throw new Error('JEFATURA_TURNO_SIN_ESQUEMA · el pedido de un agente necesita su esquema de salida (sin esquema no hay molde ni contrato)')
// dry_run OBLIGATORIO y booleano (diseño v4 §2): ausente o no booleano = se DETIENE, nunca se lee como «real»
if (typeof t.pedido.dry_run !== 'boolean') throw new Error('JEFATURA_TURNO_SIN_DRY_RUN · turno.pedido.dry_run debe ser booleano (true/false) · se DETIENE')

return [{ json: { revision_id: String(body.revision_id), turno: t, dry_run: t.pedido.dry_run === true } }]

// ② ARMAR EL PEDIDO · CC#2 · J4 · 2026-10-13 · el cuerpo que se manda a /api/agents/run-sdk (el agente solo se invoca desde un flujo con workflow_id) o, en modo seco, la respuesta SIMULADA.
// 🔴 En modo seco NO se llama a ningún proveedor ni al corredor: la respuesta sale de un molde válido por esquema (el «modelo simulado»), como en el turno de la oficina (r78).
// 🔴 Un esquema SIN molde no mata la ejecución ni la deja «corriendo»: devuelve un error VISIBLE al motor y la revisión cierra `fallida`.
// 🔴 `force_restart: true` y `dispatch_key` propios del paso: una respuesta vieja guardada no se reutiliza (lección del flujo de prueba).
// 🔴 Regla dura del editor (diseño v4 §2 y §9): `extra` lleva SOLO claves de una lista cerrada; JAMÁS `workflow_execution_id` (los ids de ejecución van arriba del cuerpo). Y el nodo «Agente» manda siempre `x-skip-editor-middleware: 1`.
// `pedido.simulacion` (solo con dry_run=true) fuerza ramas: fichas ninguna|sugerencia|bloquea · toma todo|nada · productor ok|formato_roto|formato_roto_siempre|muerto · version_nueva mejora|empeora|demasiado_corta · largo_a (largo del plan A) · donde.
const e = $input.first().json
const t = e.turno
const p = t.pedido

// ── lectura del propio pedido: las fichas («- [id] (gravedad) en …», como las arma la oficina) y los refs del kit / carrusel / imágenes
const idsDeFichas = (task) => [...String(task).matchAll(/^- \[([^\]\n]+)\] \((?:bloquea|sugerencia)\)/gm)].map((m) => m[1])
const indices = (task) => [...String(task).matchAll(/índice (\d+)/g)].map((m) => Number(m[1]))
const refsDeKit = (task) => [...String(task).matchAll(/^- (e\d+):/gm)].map((m) => m[1])
const refsDe = (task) => { const kit = refsDeKit(task); if (kit.length) return kit; const m = /Roles de lámina posibles[^:\n]*:\s*([^\n]+)/.exec(String(task)); return m ? m[1].split(',').map((x) => x.trim()).filter(Boolean) : [] }
const refsAGenerar = (task) => { const i = String(task).search(/## Imágenes que hay que GENERAR/); if (i < 0) return []; const sec = String(task).slice(i).split(/\n## /)[0]; return [...sec.matchAll(/^- ([^:\n]+):/gm)].map((m) => m[1].trim()) }
const sim = e.dry_run === true && p.simulacion && typeof p.simulacion === 'object' ? p.simulacion : {}
const toma = sim.toma === 'nada' ? 'nada' : 'todo'
const respuestasDe = (task) => idsDeFichas(task).map((id) => (toma === 'nada' ? { id, estado: 'no_tomada', razon: '(simulado) no lo tomo' } : { id, estado: 'tomada', razon: '(simulado) lo tomo' }))
const algunaTomada = (rs) => rs.some((r) => r.estado === 'tomada')
// el plan simulado: tres largos según el caso (la comparación contra A la hace el código de la planeación; aquí solo se fabrica el texto)
const textoDePlan = () => {
  const a = Number.isFinite(Number(sim.largo_a)) && Number(sim.largo_a) > 0 ? Number(sim.largo_a) : 25000
  const objetivo = sim.version_nueva === 'demasiado_corta' ? Math.floor(a * 0.3) : a
  const marca = sim.version_nueva === 'empeora' ? ' A calcular · TBD ·' : ''
  const base = '(simulado) línea del plan corregido.' + marca + '\n'
  return base.repeat(Math.ceil(objetivo / base.length)).slice(0, objetivo)
}

// ── moldes del modelo simulado: UNO por esquema que la jefatura puede pedir (los de la oficina, que la jefatura reutiliza, y los nuevos de re-entrega por tipo)
const SIMULADOS = {
  // jefe-marketing
  'fichas.v1': () => ({ fichas: sim.fichas === 'bloquea' || sim.fichas === 'sugerencia' ? [{ que: '(simulado) hallazgo de prueba', donde: String(sim.donde || 'texto'), contra_que: '(simulado) el manual', gravedad: sim.fichas, propuesta: '(simulado) propuesta de prueba' }] : [] }),
  // pieza (oficina): resoluciones por dueño
  'resolucion.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { pieza: { pie_de_foto: '(simulado) pie de foto corregido', hashtags: [] } } : {}) } },
  'resolucion_solo.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_copy_base.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_copy_kit.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_estructura.v1': (task) => ({ respuestas: respuestasDe(task) }),
  'resolucion_laminas.v1': (task) => ({ respuestas: respuestasDe(task) }),
  // estrategia (objeto completo), calendario (por fila o tanda) y plan (texto completo): la re-entrega de cada tipo
  'resolucion_objeto.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { objeto: { simulado: true } } : {}) } },
  'resolucion_parcial.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { filas: [] } : {}) } },
  // 🔴 el FORMATO real del texto largo del plan (bloque delimitado o esquema ≥ 40.000) lo decide la condición 1 de CC#3 (§13.5); este molde es lo único que cambia cuando se decida
  'resolucion_plan.v1': (task) => { const rs = respuestasDe(task); return { respuestas: rs, ...(algunaTomada(rs) ? { texto_completo: textoDePlan() } : {}) } },
  // 🔴 EL PLAN REAL (condición 1 de CC#3): texto plano + bloque de resolución al final (no un JSON con 25–34 mil caracteres adentro). Si no se tomó nada, solo el bloque.
  'plan_texto_y_resolucion.v1': (task) => { const rs = respuestasDe(task); const bloque = '<<<RESOLUCION>>>' + String.fromCharCode(10) + JSON.stringify({ respuestas: rs }) + String.fromCharCode(10) + '<<<FIN_RESOLUCION>>>'; return algunaTomada(rs) ? textoDePlan() + String.fromCharCode(10) + bloque : bloque },
  // oficina: pasos de producción que la jefatura NO ejecuta pero cuyos moldes se conservan idénticos para la prueba de igualdad (§13.3)
  'visual_direction.v1': () => ({ resumen: '(simulado) dirección visual', decision: { modo: 'generada', motivo: '(simulado)' }, reglas_de_imagen: { obligatorio: [], prohibido: [] } }),
  'prompts.v1': () => ({ prompts: [{ prompt: '(simulado) un plato visto desde arriba con luz natural lateral, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) cenital' }, { prompt: '(simulado) el mismo plato a nivel de mesa con fondo desenfocado, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) nivel de mesa' }] }),
  'observacion_imagen.v1': (task) => { const ix = indices(task); return { imagenes: ix.map((indice) => ({ indice, reglas: [], texto_en_imagen: [], marcas: [], personas: 0 })), preferencia: ix } },
  'observacion_imagenes.v1': (task) => { const ix = indices(task); return { imagenes: ix.map((indice) => ({ indice, reglas: [], texto_en_imagen: [], marcas: [], personas: 0 })), preferencia: ix } },
  'pieza_post.v1': () => ({ pie_de_foto: '(simulado) pie de foto de prueba', hashtags: [] }),
  'direccion_imagenes.v1': (task) => { const refs = refsDe(task); return { resumen: '(simulado) dirección visual', estilo: '(simulado)', imagenes: refs.length ? [{ ref: refs[0], modo: 'generada', motivo: '(simulado)' }] : [], reglas_de_imagen: { obligatorio: [], prohibido: [] } } },
  'prompts_por_ref.v1': (task) => ({ imagenes: refsAGenerar(task).map((ref) => ({ ref, prompts: [{ prompt: '(simulado) un plato visto desde arriba con luz natural lateral, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) cenital' }, { prompt: '(simulado) el mismo plato a nivel de mesa con fondo desenfocado, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) nivel de mesa' }] })) }),
  'copy_base.v1': () => ({ texto_base: 'Primera línea simulada\nSegunda línea simulada\nTercera línea simulada\nCuarta línea simulada\nEscríbenos', pie_de_foto: '(simulado) pie de foto de prueba', hashtags: [] }),
  'laminas.v1': () => ({ laminas: [{ rol: 'hook', headline: 'Primera línea simulada' }, { rol: 'problem', headline: 'Segunda línea simulada' }, { rol: 'reframe', headline: 'Tercera línea simulada' }, { rol: 'benefit', headline: 'Cuarta línea simulada' }, { rol: 'cta', headline: 'Escríbenos', cta: 'Escríbenos' }] }),
  'estructura.v1': (task) => ({ elementos: refsDeKit(task).map((ref) => ({ ref, rol: '(simulado) rol', beat: '(simulado) beat', mood: '(simulado) mood' })) }),
  'copy_kit.v1': (task) => ({ elementos: refsDeKit(task).map((ref) => ({ ref, headline: '(simulado) titular' })) }),
}

const ERROR = (msg) => ({ ...e, simulado: true, resultado_body: { accion: 'resultado', revision_id: e.revision_id, n: t.n, error: msg, costo_usd: 0, workflow_execution_id: $execution.id } })

if (e.dry_run === true) {
  // FUENTE ÚNICA DE MOLDES (certificación de CC#3 · J2/J3 reparo 2): si la ruta entregó su `pedido.molde`, el seco contesta ESO (lo que la ruta sabe leer); los moldes de abajo son solo el respaldo cuando la ruta no trae molde (`molde_de: 'flujo'`)
  const deLaRuta = p.molde && typeof p.molde === 'object' && !Array.isArray(p.molde) ? p.molde : null
  if (deLaRuta) {
    if (typeof deLaRuta.texto !== 'string') {
      // el productor murió en la simulación de la ruta: no contesta (el vigía lo re-arma); cualquier otro motivo es un error visible, nunca «corriendo»
      if (sim.productor === 'muerto') return []
      return [{ json: { ...ERROR('JEFATURA_MOLDE_DE_LA_RUTA_SIN_TEXTO · ' + String(deLaRuta.error || 'la ruta no entregó texto para este paso')), molde_de: 'ruta' } }]
    }
    return [{ json: { ...e, simulado: true, molde_de: 'ruta', resultado_body: { accion: 'resultado', revision_id: e.revision_id, n: t.n, texto: deLaRuta.texto, costo_usd: 0, workflow_execution_id: $execution.id } } }]
  }
  const molde = SIMULADOS[p.esquema]
  // un esquema sin molde NO mata la ejecución (la revisión se quedaría «corriendo» en silencio): el motor recibe el error y la revisión falla visible
  if (!molde) return [{ json: ERROR('JEFATURA_SIN_MOLDE_SIMULADO · no hay respuesta simulada para el esquema ' + JSON.stringify(p.esquema)) }]
  // productor muerto: no contesta nunca (el vigía lo re-arma a los 12 min); en el seco la ejecución termina sin registrar nada, a propósito
  if (sim.productor === 'muerto') return []
  const roto = sim.productor === 'formato_roto_siempre' || (sim.productor === 'formato_roto' && p.reintento_formato !== true)
  const m = roto ? null : molde(p.task)
  const texto = roto ? '{"respuestas": [ {"id": ' : (typeof m === 'string' ? m : JSON.stringify(m)) // un molde de TEXTO (el plan) devuelve la cadena tal cual
  return [{ json: { ...e, simulado: true, molde_de: 'flujo', resultado_body: { accion: 'resultado', revision_id: e.revision_id, n: t.n, texto, costo_usd: 0, workflow_execution_id: $execution.id } } }]
}

// ── real: el pedido a run-sdk. Sin tope de gasto del paso NO se paga (el SDK acota el costo con max_budget_usd)
if (!(typeof p.max_budget_usd === 'number' && p.max_budget_usd > 0)) throw new Error('JEFATURA_SIN_TOPE_DEL_PASO · el pedido real no trae max_budget_usd (> 0) · no se paga un paso sin tope · se DETIENE')
const PERMITIDAS = ['indicacion_jefatura', 'paso_de_la_jefatura', 'revision_id', 'dispatch_key']
const extra = {}
for (const k of PERMITIDAS) if (p.extra && p.extra[k] !== undefined) extra[k] = p.extra[k]
extra.dispatch_key = t.dispatch_key
const cuerpo = {
  agent: p.agent_name,
  task: p.task,
  client_id: p.client_id,
  workflow_id: $workflow.id,
  workflow_execution_id: $execution.id,
  callback_url: $execution.resumeUrl,
  // la vuelta la entrega el corredor cuando el agente puede; si no puede, run-sdk lo ignora y la vuelta sigue por Vercel con la recuperación del resultado
  callback_mode: 'runner',
  force_restart: true,
  dry_run: false,
  max_budget_usd: p.max_budget_usd,
  thinking_mode: p.thinking_mode || 'disabled',
  extra,
  ...(Array.isArray(p.images) && p.images.length ? { images: p.images, images_mode: 'base64' } : {}),
}
return [{ json: { ...e, simulado: false, cuerpo } }]

// ② ¿ACEPTÓ EL PEDIDO? · CC#2 · 2026-10-09 · mismo criterio que la pieza: run-sdk contesta SÍNCRONO 202 `{accepted:true}` si acepta (la vuelta llega después por el callback) o un RECHAZO con `error`.
// Un rechazo síncrono significa que el agente NO arrancó: se avisa YA a la jefatura (resultado con error) en lugar de esperar la espera entera.
const c = $('② Armar el pedido').first().json
const e = $input.first().json || {}
const r = e.body && typeof e.body === 'object' ? e.body : e
// el nodo HTTP falló (red, tiempo): n8n entrega `{error:{message…}}` con `error` OBJETO · el rechazo de run-sdk trae `error` como TEXTO
if (r.error && typeof r.error === 'object') {
  return [{ json: { ...c, aceptado: false, resultado_body: { accion: 'resultado', revision_id: c.revision_id, n: c.turno.n, error: 'JEFATURA_PEDIDO_NO_LLEGO · ' + String(r.error.message || r.error.name || 'sin detalle').slice(0, 200), costo_usd: 0, workflow_execution_id: $execution.id } } }]
}
if (r.accepted === true) return [{ json: { ...c, aceptado: true } }]
const partes = [r.error, r.code, r.detail].filter((x) => x !== undefined && x !== null && x !== '')
return [{ json: { ...c, aceptado: false, resultado_body: { accion: 'resultado', revision_id: c.revision_id, n: c.turno.n, error: 'JEFATURA_PEDIDO_RECHAZADO · ' + (partes.length ? partes.map(String).join(' · ').slice(0, 240) : JSON.stringify(r).slice(0, 200)), costo_usd: 0, workflow_execution_id: $execution.id } } }]

// ② LA VUELTA DEL AGENTE (o el portero) · CC#2 · 2026-10-09 · convierte lo que volvió en el cuerpo de `POST /api/jefatura/turnos {accion:'resultado'}`.
// Un fallo declarado del agente (`success:false`: corte por tope, etc.) NO es una vuelta: su texto, si trae, es PARCIAL y no se manda como respuesta (se manda el error).
// El costo es el que reporta el corredor (el libro de la sala lo suma); sin costo reportado se manda 0 y la sala lo declara.
const c = $('② Armar el pedido').first().json
const e = $input.first().json || {}
const cuerpo = e.body ? e.body : e
const fallo = cuerpo.success === false ? String(cuerpo.error || cuerpo.error_kind || 'sin detalle') : null
const texto = fallo ? '' : String(cuerpo.response || cuerpo.result || cuerpo.output || cuerpo.text || '')
const costo = typeof cuerpo.cost_usd === 'number' ? cuerpo.cost_usd : (typeof cuerpo.costUsd === 'number' ? cuerpo.costUsd : 0)
const body = { accion: 'resultado', revision_id: c.revision_id, n: c.turno.n, costo_usd: costo, workflow_execution_id: $execution.id, workflow_id: $workflow.id }
if (fallo) body.error = 'el agente FALLÓ · ' + fallo + (cuerpo.partial === true ? ' · (había texto parcial: no se usa)' : '')
else if (texto.trim() === '') body.error = 'la vuelta del agente llegó vacía (o se agotó la espera)'
else body.texto = texto
if (typeof cuerpo.tokens_in === 'number') body.tokens_in = cuerpo.tokens_in
if (typeof cuerpo.tokens_out === 'number') body.tokens_out = cuerpo.tokens_out
return [{ json: { ...c, resultado_body: body } }]

// ③ ¿Y AHORA? · CC#2 · J4 · 2026-10-13 · decide qué sigue con la respuesta REAL de `POST /api/jefatura/turnos` (statusCode + body).
//   200 `esperar` → el SIGUIENTE paso: se vuelve a despertar este mismo flujo (una ejecución por paso: ninguna pasa de unos minutos)
//   200 `cerrado` → la revisión terminó (limpia, con desacuerdo, sin segunda mirada, incompleta por tope o fallida): se ENTREGA al llamador según `devolver_a`:
//                     · `devolver.tipo = 'webhook'` → se manda `devolver.cuerpo` a `devolver.url` (SOLO si la dirección es de nuestro n8n o de nuestro Vercel: nada sale a un tercero)
//                     · `devolver.tipo = 'sala_ref'` o ausente con `sala_ref` → el CABLE a la sala con el resultado REAL
//                     · `devolver.tipo = 'ninguno'` → nada (la ruta ya guardó todo; p. ej. las pruebas de la jefatura)
//   cualquier otra respuesta (409 turno no esperado, 5xx…) → se DETIENE con su motivo (nunca se da por bien)
const c = $('⓪ Entrada · llave').first().json
const e = $input.first().json || {}
if (e.error && typeof e.error === 'object') throw new Error('JEFATURA_RESULTADO_NO_LLEGO · POST /api/jefatura/turnos falló antes de recibir respuesta (' + String(e.error.message || e.error.name || 'sin detalle').slice(0, 160) + ')')
